import Foundation

public enum HTMLReport {
    public static func escape(_ text: String) -> String {
        text.replacingOccurrences(of: "&", with: "&amp;").replacingOccurrences(of: "<", with: "&lt;").replacingOccurrences(of: ">", with: "&gt;").replacingOccurrences(of: "\"", with: "&quot;").replacingOccurrences(of: "'", with: "&#39;")
    }
    public static func render(_ snapshot: AuditSnapshot, baseline: AuditSnapshot?, policy: AuditPolicy) -> String {
        let findings = snapshot.findings ?? FindingEngine.evaluate(snapshot, baseline: baseline, policy: policy)
        let changes = baseline.map { AuditComparison.changes(baseline: $0, current: snapshot) } ?? []
        let privacy = snapshot.redacted == true ? "<p class='finding review'><strong>REDACTED EXPORT</strong> Personal paths, web addresses and free-text context/exception notes omitted. Review before sharing; app names, versions, identifiers and evidence may still be sensitive.</p>" : ""
        let e = escape
        let workflow = "<section><h2>Audit context, age evidence and network mode</h2><p class='evidence'>" + e(snapshot.workflowSummary) + "</p></section>"
        let decisions: (AuditFinding) -> String = { item in
            guard let value = item.exception else { return "<p><strong>Decision:</strong> Unreviewed</p>" }
            return "<p class='evidence'><strong>" + e(value.status(for: item, now: snapshot.captured)) + "</strong><br>" + e(value.description) + "</p>"
        }
        let findingHTML = findings.isEmpty ? "<p>No findings recorded. Review coverage before interpreting this result.</p>" : findings.map { item in
            "<article class='finding \(item.severity == .action ? "action" : item.severity == .review ? "review" : "unknown")'><div class='badge'>\(e(item.severity.rawValue))</div><h3>\(e(item.title))</h3><p><strong>\(e(item.app))</strong> <span class='path'>\(e(item.path))</span></p><p class='evidence'>\(e(String(item.evidence.prefix(1800))))</p><p><strong>Suggested next step:</strong> \(e(item.nextStep))</p>\(decisions(item))</article>"
        }.joined()
        let changeHTML = changes.isEmpty ? "<p>\(baseline == nil ? "No comparison baseline selected." : "No comparable inventory, hash or signing changes recorded.")</p>" : "<table><thead><tr><th>Change</th><th>App</th><th>Evidence</th></tr></thead><tbody>" + changes.map { "<tr><td>\(e($0.kind))</td><td>\(e($0.name))</td><td class='evidence'>\(e($0.summary))</td></tr>" }.joined() + "</tbody></table>"
        let rows = snapshot.apps.map { app -> String in
            let security = snapshot.evidence[app.id]; let update = UpdateRouting.result(app, recorded: snapshot.updates[app.id], at: snapshot.captured); let hashes = snapshot.integrity?[app.id]
            let updateChecked = (app.classification.managedByMacOS || app.appStore) ? "Availability not checked; channel only" : (update?.checked.formatted() ?? "Not checked")
            let install = security?.installDate ?? app.created
            let manual = snapshot.developerLinks?[DeveloperLinks.key(app)] ?? DeveloperLinks()
            let links = manual.entries.map { "User supplied · " + $0.0 + ": " + $0.1 }.joined(separator: "; ")
            let catalog = manual.website.isEmpty ? (update?.homepage.map { "Catalog homepage: " + $0 } ?? "") : ""
            let hashText = hashes.map { h in h.hashes.keys.sorted().map { "\($0): \(h.hashes[$0] ?? "")" }.joined(separator: "\n") } ?? "Not collected"
            return "<tr><td><strong>\(e(app.name))</strong><br><span class='path'>\(e(app.bundleID))<br>\(e(app.path))</span><br>Version \(e(app.version)) / build \(e(app.build))<br><span class='evidence'>\(e(snapshot.workflowEvidence(app)))</span><br>Architecture: \(e(app.architecture ?? "Unknown"))<br>\(e(links))<br>\(e(catalog))</td><td>\(e(security?.signature ?? "Not checked"))<br>\(e(security?.publisher ?? "Publisher not collected"))<br>Team: \(e(security?.teamID ?? "Unknown"))<br>Signed ID: \(e(security?.signedID ?? "Unknown"))<br>Gatekeeper: \(e(security?.gatekeeper ?? "Not checked"))<br>Notarization: \(e(security?.notarization ?? "Not checked"))<br><span class='small'>Checked: \(e(security?.checked.formatted() ?? "Not checked"))</span></td><td>Install evidence: \(e(install?.formatted() ?? "Unknown"))<br><span class='small'>\(e(security?.installSource ?? "Filesystem creation estimate; receipts not checked"))</span><br>Last used: \(e(app.lastUsed?.formatted() ?? "Unknown"))<br>Receipts: \(e(security?.receipts.map(\.packageID).joined(separator: "; ") ?? "Not checked"))</td><td>\(e(update?.status ?? "Not checked"))<br>Latest: \(e(update?.latest ?? "Unknown"))<br><span class='small'>\(e(update?.identity ?? "Identity not checked"))<br>\(e(update?.source ?? ""))<br>Checked: \(e(updateChecked))</span></td></tr><tr class='hashrow'><td colspan='4'><strong>SHA-256:</strong> <span class='hash'>\(e(hashText))</span>\(hashes?.errors.isEmpty == false ? "<br>Unavailable: " + e(hashes!.errors.keys.sorted().joined(separator: ", ")) : "")</td></tr>"
        }.joined()
        let notes = snapshot.warnings.map { "<li>\(e($0))</li>" }.joined()
        let scopeNotes = baseline.map { AuditComparison.scopeNotes(baseline: $0, roots: snapshot.roots, warnings: snapshot.warnings) } ?? []
        return """
        <!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; img-src data:; base-uri 'none'; form-action 'none'"><title>Xtracsys · App Audit report</title><style>
        :root{font-family:-apple-system,BlinkMacSystemFont,Arial,sans-serif;color:#171717;background:#F7F6F2}body{margin:0}main{max-width:1200px;margin:32px auto;background:white;padding:36px;box-shadow:0 8px 40px #11223312}header{display:flex;align-items:center;gap:20px}.brand-logo{width:76px;height:76px;object-fit:contain;background:white;padding:6px;border-radius:10px}.wordmark{letter-spacing:3px;font-size:11px;font-weight:700;margin:0 0 5px}h1{font-size:32px;margin:0;color:#B24630}h2{font-size:21px;margin:30px 0 14px;border-bottom:2px solid #d8e5e8;padding-bottom:8px}h3{font-size:16px;margin:8px 0}p,li{line-height:1.5}.muted,.small{color:#52666e}.small{font-size:11px}.stats{display:flex;gap:14px;margin:20px 0}.stat{flex:1;background:#F7F6F2;padding:16px;border-radius:8px}.stat b{display:block;font-size:25px}.finding{border-left:4px solid #8eabb4;padding:12px 18px;background:#F7F6F2;margin:12px 0;break-inside:avoid}.finding.action{border-color:#b24628}.finding.review{border-color:#b68116}.badge{font-size:11px;text-transform:uppercase;font-weight:700}.path,.evidence,.hash{overflow-wrap:anywhere;word-break:break-word}.path{font-size:11px;color:#52666e}.evidence{white-space:pre-wrap;font-size:12px}.hash{font:10px ui-monospace,Menlo,monospace;white-space:pre-wrap}table{width:100%;border-collapse:collapse;table-layout:fixed;font-size:11px}th{text-align:left;background:#F0EDE8;color:#171717}td,th{padding:10px;border:1px solid #dce5e8;vertical-align:top;overflow-wrap:anywhere}thead{display:table-header-group}tr{break-inside:avoid}.hashrow td{background:#F7F6F2;padding:7px 10px}footer{margin-top:28px;font-size:11px;color:#52666e;border-top:1px solid #dce5e8;padding-top:12px}@page{size:A4 landscape;margin:13mm}@media print{:root{background:white}main{margin:0;max-width:none;padding:0;box-shadow:none}h1{font-size:25px}h2{break-after:avoid}.stats{gap:8px}.stat{padding:10px}a{color:inherit}table{font-size:9px}td,th{padding:7px}.small{font-size:9px}.hash{font-size:8px}.finding{font-size:11px}.evidence{font-size:10px}}
        </style></head><body><main><header><img class="brand-logo" src="\(Brand.logoDataURL)" alt="Xtracsys logo"><div><p class="wordmark">XTRACSYS</p><h1>App Audit</h1><p class="muted">Application security review · captured \(e(snapshot.captured.formatted()))</p></div></header><div class="stats"><div class="stat"><b>\(snapshot.apps.count)</b>Applications</div><div class="stat"><b>\(findings.filter { $0.severity == .action }.count)</b>Action needed</div><div class="stat"><b>\(findings.filter { $0.severity == .review }.count)</b>Review</div><div class="stat"><b>\(findings.filter { $0.severity == .unknown }.count)</b>Unknown</div></div>
        \(privacy)\(workflow)<h2>Coverage and interpretation</h2><p>Scan folders: \(e(snapshot.roots.joined(separator: "; "))). Security evidence: \(snapshot.evidence.count)/\(snapshot.apps.count) apps. Integrity: \(snapshot.integrity?.count ?? 0)/\(snapshot.apps.count) apps. Update observations/routes: \(snapshot.updates.count)/\(snapshot.apps.count) apps.</p><p>Policy: \(policy.enabled ? "enabled" : "disabled"); \(policy.rules.count) app rules; allow-only-listed: \(policy.allowOnlyListed ? "yes" : "no"). Baseline: \(e(baseline?.captured.formatted() ?? "None"))</p><ul>\(notes)\(scopeNotes.map { "<li>" + e($0) + "</li>" }.joined())</ul><p class="small">Unknown evidence is not a clean or unsafe verdict. Strict signature validation, Gatekeeper and notarization answer different questions. Receipt dates are installer events, not proof of original installation. SHA-256 covers the main executable, Info.plist and CodeResources when readable; it is not a hash of every app file. Saved/imported reports and snapshots are unauthenticated observations.</p>
        <h2>Findings and suggested next steps</h2>\(findingHTML)<h2>Changes from baseline</h2>\(changeHTML)<h2>Application evidence</h2><table><thead><tr><th>Application / version / location</th><th>Signing and platform checks</th><th>Date provenance</th><th>Update evidence</th></tr></thead><tbody>\(rows)</tbody></table><footer>Generated by Xtracsys App Audit · local audit evidence, not a malware or CVE verdict. Review vendor identity and source coverage before acting. No inspected app or downloaded installer was executed.</footer></main></body></html>
        """
    }
}
